package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
	"regexp"
	"strings"
	"sync"
	"time"
)

const (
	maxRetries    = 3
	retryDelay    = 500 * time.Millisecond
	rateLimit     = 100
	ratePeriod    = time.Minute
)

type RateLimiter struct {
	mu       sync.Mutex
	counts   map[string]int
	resetAt  map[string]time.Time
}

func NewRateLimiter() *RateLimiter {
	return &RateLimiter{
		counts:  make(map[string]int),
		resetAt: make(map[string]time.Time),
	}
}

func (rl *RateLimiter) Allow(clientIP string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	now := time.Now()
	if resetTime, exists := rl.resetAt[clientIP]; !exists || now.After(resetTime) {
		rl.counts[clientIP] = 0
		rl.resetAt[clientIP] = now.Add(ratePeriod)
	}
	rl.counts[clientIP]++
	return rl.counts[clientIP] <= rateLimit
}

type ProxyConfig struct {
	AllowedHostPattern string
	BlockedPaths       []string
	HeaderSanitizer    *regexp.Regexp
}

func DefaultConfig() *ProxyConfig {
	// Pattern validates allowed upstream host format
	// Accepts: subdomain.example.com, sub-domain.test.org, etc.
	hostPattern := `^([a-zA-Z0-9]([a-zA-Z0-9\-]*[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$`

	// Sanitizer removes potentially dangerous header values
	// Matches sequences that could indicate header injection attempts
	headerSanitizer := regexp.MustCompile(`^[\w\-]+(\s*[,;]\s*[\w\-]+)*$`)

	return &ProxyConfig{
		AllowedHostPattern: hostPattern,
		BlockedPaths:       []string{"/admin", "/internal", "/.env"},
		HeaderSanitizer:    headerSanitizer,
	}
}

type Proxy struct {
	config      *ProxyConfig
	rateLimiter *RateLimiter
	hostRegex   *regexp.Regexp
	client      *http.Client
}

func NewProxy(config *ProxyConfig) (*Proxy, error) {
	hostRegex, err := regexp.Compile(config.AllowedHostPattern)
	if err != nil {
		return nil, fmt.Errorf("invalid host pattern: %w", err)
	}
	return &Proxy{
		config:      config,
		rateLimiter: NewRateLimiter(),
		hostRegex:   hostRegex,
		client: &http.Client{
			Timeout: 30 * time.Second,
		},
	}, nil
}

func (p *Proxy) isPathBlocked(path string) bool {
	normalized := strings.ToLower(path)
	for _, blocked := range p.config.BlockedPaths {
		if strings.HasPrefix(normalized, blocked) {
			return true
		}
	}
	return false
}

func (p *Proxy) validateUpstreamHost(host string) bool {
	return p.hostRegex.MatchString(host)
}

func (p *Proxy) sanitizeHeaders(headers http.Header) http.Header {
	clean := make(http.Header)
	for key, values := range headers {
		if strings.HasPrefix(strings.ToLower(key), "x-proxy-") {
			continue
		}
		for _, v := range values {
			if p.config.HeaderSanitizer.MatchString(v) {
				clean.Add(key, v)
			}
		}
	}
	return clean
}

func (p *Proxy) forwardWithRetry(req *http.Request) (*http.Response, error) {
	var lastErr error
	for attempt := 0; attempt <= maxRetries; attempt++ {
		if attempt > 0 {
			time.Sleep(retryDelay * time.Duration(attempt))
		}
		resp, err := p.client.Do(req)
		if err != nil {
			lastErr = err
			continue
		}
		if resp.StatusCode >= 500 {
			resp.Body.Close()
			lastErr = fmt.Errorf("upstream returned %d", resp.StatusCode)
			continue
		}
		return resp, nil
	}
	return nil, fmt.Errorf("all retries exhausted: %w", lastErr)
}

func (p *Proxy) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	clientIP := strings.Split(r.RemoteAddr, ":")[0]

	if !p.rateLimiter.Allow(clientIP) {
		http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	if p.isPathBlocked(r.URL.Path) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}

	upstreamHost := r.Header.Get("X-Upstream-Host")
	if upstreamHost == "" {
		http.Error(w, "missing upstream host", http.StatusBadRequest)
		return
	}

	if !p.validateUpstreamHost(upstreamHost) {
		http.Error(w, "invalid upstream host", http.StatusBadRequest)
		return
	}

	targetURL := fmt.Sprintf("https://%s%s", upstreamHost, r.URL.Path)
	proxyReq, err := http.NewRequestWithContext(r.Context(), r.Method, targetURL, r.Body)
	if err != nil {
		http.Error(w, "failed to create request", http.StatusInternalServerError)
		return
	}

	proxyReq.Header = p.sanitizeHeaders(r.Header)

	resp, err := p.forwardWithRetry(proxyReq)
	if err != nil {
		http.Error(w, "upstream unavailable", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	for key, values := range resp.Header {
		for _, v := range values {
			w.Header().Add(key, v)
		}
	}
	w.WriteHeader(resp.StatusCode)
	io.Copy(w, resp.Body)
}

func main() {
	config := DefaultConfig()
	proxy, err := NewProxy(config)
	if err != nil {
		log.Fatalf("failed to create proxy: %v", err)
	}

	log.Println("Starting proxy on :8080")
	log.Fatal(http.ListenAndServe(":8080", proxy))
}
